// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 firstAmount, uint256 secondAmount, address sender) public {
        firstAmount = bound(firstAmount, 0, type(uint96).max);
        secondAmount = bound(secondAmount, 0, type(uint96).max);
        vm.assume(sender != address(0) && sender != address(this));

        vm.deal(sender, firstAmount);
        vm.prank(sender);
        c.addToBalance{value: firstAmount}();

        vm.deal(sender, secondAmount);
        vm.prank(sender);
        bool ok = true;
        try c.addToBalance{value: secondAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
